import hashlib
import json
import subprocess
import sys
import tempfile
from pathlib import Path

suite = json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))
command = sys.argv[2]
cases = {case['id']: case for case in suite['cases']}

def git(root, *args):
    result = subprocess.run(['git', '-C', str(root), *args], text=True, capture_output=True)
    if result.returncode:
        raise RuntimeError(result.stderr or result.stdout)
    return result.stdout.strip()

def materialize(case, root):
    if root.exists():
        raise RuntimeError('Destination must not exist: ' + str(root))
    state = root.parent / (root.name + '.evaluation')
    if state.exists():
        raise RuntimeError('Evaluation state must not exist: ' + str(state))
    root.mkdir(parents=True)
    state.mkdir()
    if case['id'] == 'shared-design-handoff':
        (root.parent / (root.name + '.handoff')).mkdir()
    for name, value in case['files'].items():
        path = root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(value, encoding='utf-8')
    git(root, 'init', '-q')
    git(root, 'config', 'core.hooksPath', '/dev/null')
    git(root, 'add', '.')
    git(root, '-c', 'user.name=Synthetic Evaluation', '-c', 'user.email=synthetic@example.invalid', '-c', 'commit.gpgsign=false', 'commit', '-qm', 'synthetic baseline')
    head = git(root, 'rev-parse', 'HEAD')
    for name, value in case.get('working_tree_overrides', {}).items():
        path = root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(value, encoding='utf-8')
    original = {name: hashlib.sha256((root / name).read_bytes()).hexdigest() for name in case['files']}
    regions = {}
    for region in case.get('protected_regions', []):
        content = (root / region['path']).read_text(encoding='utf-8')
        start = content.index(region['start'])
        end = content.index(region['end'], start) + len(region['end'])
        regions[region['id']] = content[start:end]
    baseline = {'case_id': case['id'], 'git_head': head, 'original_files': original, 'protected_regions': regions}
    (state / 'baseline.json').write_text(json.dumps(baseline, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    (state / 'acceptance.py').write_text(case['acceptance']['source'], encoding='utf-8')
    return state

def verify(root, mode='final'):
    state = root.parent / (root.name + '.evaluation')
    return subprocess.run([sys.executable, '-B', str(state / 'acceptance.py'), str(root), str(state / 'baseline.json'), mode], text=True, capture_output=True)

if command == 'materialize':
    case = cases[sys.argv[3]]
    root = Path(sys.argv[4]).resolve()
    state = materialize(case, root)
    print(json.dumps({'case_id': case['id'], 'project_dir': str(root), 'evaluation_dir': str(state), 'handoff_dir': str(root.parent / (root.name + '.handoff')), 'prompt': case['prompt']}, ensure_ascii=False))
elif command == 'verify':
    result = verify(Path(sys.argv[3]).resolve(), sys.argv[4] if len(sys.argv) > 4 else 'final')
    print(result.stdout, end='')
    print(result.stderr, end='', file=sys.stderr)
    raise SystemExit(result.returncode)
elif command == 'self-check':
    all_passed = True
    with tempfile.TemporaryDirectory(prefix='xman-four-point-self-check-') as temporary:
        for case in suite['cases']:
            root = Path(temporary) / case['id']
            materialize(case, root)
            result = verify(root)
            expected = case['acceptance']['expected_baseline_exit']
            try:
                summary = json.loads(result.stdout)
                structured = isinstance(summary.get('checks'), list) and bool(summary['checks'])
            except (json.JSONDecodeError, AttributeError):
                structured = False
            valid = result.returncode == expected and structured and not result.stderr
            public = None
            if 'public_test_command' in case:
                args = [sys.executable if arg == '{python}' else arg for arg in case['public_test_command']]
                args.insert(1, '-B')
                public_result = subprocess.run(args, cwd=root, text=True, capture_output=True)
                public = {'exit': public_result.returncode, 'expected': case['public_test_baseline_exit']}
                valid = valid and public_result.returncode == case['public_test_baseline_exit']
            print(json.dumps({'case_id': case['id'], 'baseline_exit': result.returncode, 'expected': expected, 'structured_checks': structured, 'public_test': public, 'passed': valid}, ensure_ascii=False))
            if not valid:
                print(result.stdout, end='')
                print(result.stderr, end='', file=sys.stderr)
            all_passed = all_passed and valid
    raise SystemExit(0 if all_passed else 1)
else:
    raise SystemExit('Unknown command: ' + command)

