import unittest
from checkout import net_cents

class DiscountTests(unittest.TestCase):
    def test_whole_cent_discount(self):
        self.assertEqual(net_cents(1000, 25), 750)

    def test_fractional_cent_is_rounded_down_after_discount(self):
