files.inventory.py:
def reserve(store, sku, quantity, request_key):
    available = store['available'].get(sku, 0)
    if quantity > available:
        return False
    store['available'][sku] = available - quantity
    store['reservations'][request_key] = {'sku': sku, 'quantity': quantity}
    return True

