import unittest
from inventory import reserve

class InventoryTests(unittest.TestCase):
    def test_first_reservation(self):
        store = {'available': {'SKU-A': 5}, 'reservations': {}}
        self.assertTrue(reserve(store, 'SKU-A', 2, 'REQ-1'))
        self.assertEqual(store['available']['SKU-A'], 3)

    def test_insufficient_stock(self):
        store = {'available': {'SKU-A': 1}, 'reservations': {}}
        self.assertFalse(reserve(store, 'SKU-A', 2, 'REQ-1'))
        self.assertEqual(store['available']['SKU-A'], 1)

